const BUNDLE: Record<string, string> = {
  "docs/legal/privacy-v1.0.md": "# Privacy Policy\r\n\r\n**Ascension Systems** (doing business as Efficiency Architects and related product brands)  \r\n**Version:** 1.0  \r\n**Document ID:** ASC-PRIVACY-2026-1.0  \r\n**Effective Date:** July 21, 2026  \r\n**Last Updated:** July 22, 2026  \r\n**Status:** Active\r\n\r\n---\r\n\r\n## 1. Who we are\r\n\r\n**Ascension Systems** (“**Company**,” “**we**,” “**us**”) operates software and professional services under brands including Efficiency Architects, Simplifi, Simplifi Orb, Amplifi, Magnifi, Fortifi, Unifi, and Pulse (collectively, the “**Services**”).\r\n\r\nContact: freedom@efficiencyarchitects.online  \r\nAddress: 1848 Olsen Lane, Charlotte, NC 28213, United States\r\n\r\n## 2. Scope\r\n\r\nThis Privacy Policy describes how we collect, use, disclose, and protect personal information when you use our websites, portals, mobile applications, assessments, and related Services. Product-specific notices may supplement this Policy; they do not replace it.\r\n\r\n## 3. Information we collect\r\n\r\n### 3.1 Information you provide\r\n\r\n- Contact and account details (name, email, organization, role)\r\n- Billing and payment metadata processed by our payment provider (we do not store full card numbers)\r\n- Assessment, intake, and project content you submit\r\n- Support requests and correspondence\r\n- Content you upload to portals, Capture, or Communications features\r\n\r\n### 3.2 Information collected automatically\r\n\r\n- Device, browser, and app identifiers\r\n- Log data, IP address, approximate location derived from IP\r\n- Usage events needed to operate and secure the Services\r\n- Cookies and similar technologies (see our [Cookie Policy](/legal/cookies))\r\n\r\n### 3.3 Information from third parties\r\n\r\n- Payment processors (e.g., Stripe)\r\n- Email and messaging providers\r\n- Authentication and analytics providers we engage as processors\r\n- Public or client-authorized sources used for Opportunity Intelligence / research features when you request them\r\n\r\n## 4. How we use information\r\n\r\n- Provide, secure, and improve the Services\r\n- Authenticate users and prevent abuse\r\n- Process payments and fulfill purchases\r\n- Deliver proposals, websites, portals, and guided project experiences\r\n- Provide support and transactional communications\r\n- Generate AI-assisted insights and content subject to our [AI Disclosure](/legal/ai-disclosure)\r\n- Comply with law and enforce agreements\r\n\r\n## 5. Legal bases (where applicable)\r\n\r\nWhere required (e.g., GDPR-style regimes), we rely on contract performance, legitimate interests (security, product improvement), consent (where requested), and legal obligation.\r\n\r\n## 6. Sharing\r\n\r\nWe share personal information with:\r\n\r\n- Service providers acting on our instructions (hosting, email, payments, analytics, e-signature)\r\n- Professional advisors under confidentiality\r\n- Authorities when required by law\r\n- Successors in connection with a corporate transaction\r\n\r\nWe do **not** sell personal information as “sale” is commonly defined under U.S. state privacy laws. We do not share personal information for cross-context behavioral advertising except where a specific feature requires consent and you have provided it.\r\n\r\n## 7. International transfers\r\n\r\nWe may process data in the United States and other countries where our providers operate. We use appropriate safeguards where required.\r\n\r\n## 8. Retention\r\n\r\nWe retain information for as long as needed to provide the Services, meet legal and accounting requirements, resolve disputes, and enforce agreements. Project and contract records may be retained longer under professional services engagements.\r\n\r\n## 9. Security\r\n\r\nWe implement administrative, technical, and organizational measures appropriate to the nature of the Services. No method of transmission or storage is perfectly secure.\r\n\r\n## 10. Your choices and rights\r\n\r\nDepending on your location, you may have rights to access, correct, delete, or export personal information, or to object to or restrict certain processing. Contact freedom@efficiencyarchitects.online. We may verify your request before responding.\r\n\r\n### Account deletion (Simplifi Orb / Google Play)\r\n\r\nYou may delete your Simplifi Orb account and associated personal data:\r\n\r\n1. **In the app:** Settings → Delete account (requires confirmation).\r\n2. **On the web (no app install required):** https://efficiencyarchitects.online/legal/account-deletion\r\n3. **By email:** freedom@efficiencyarchitects.online with subject “Account deletion request.”\r\n\r\nDeletion revokes portal access, anonymizes contact fields on your client record, clears stored portal credentials, and removes push tokens for your account. Limited records may be retained where required for security, fraud prevention, accounting, or law.\r\n\r\n## 11. Children\r\n\r\nThe Services are not directed to children under 16 (or the age required by local law). We do not knowingly collect personal information from children.\r\n\r\n## 12. Mobile applications (including Simplifi)\r\n\r\nMobile apps may request permissions such as camera, photos, notifications, or network access to provide Capture and related features. You can revoke permissions in device settings; some features may stop working.\r\n\r\n**Public Privacy Policy URL (Google Play):** https://efficiencyarchitects.online/legal/privacy\r\n\r\n## 13. Changes\r\n\r\nWe may update this Policy by posting a new version with a revised “Last Updated” date. Material changes will be highlighted where practicable.\r\n\r\n## 14. Contact\r\n\r\nPrivacy questions: freedom@efficiencyarchitects.online\r\n",
  "docs/legal/terms-v1.0.md": "# Terms of Service\r\n\r\n**Ascension Systems** (doing business as Efficiency Architects and related product brands)  \r\n**Version:** 1.0  \r\n**Document ID:** ASC-TOS-2026-1.0  \r\n**Effective Date:** July 21, 2026  \r\n**Last Updated:** July 21, 2026  \r\n**Status:** Active\r\n\r\n---\r\n\r\n## 1. Agreement\r\n\r\nThese Terms of Service (“**Terms**”) govern access to and use of websites, portals, software subscriptions, mobile applications, and related online services (the “**Services**”) provided by **Ascension Systems** (“**Company**,” “**we**,” “**us**”).\r\n\r\nBy accessing or using the Services, you agree to these Terms. If you are accepting on behalf of an organization, you represent that you have authority to bind that organization (“**Client**”).\r\n\r\nProfessional services, websites, portals, and custom deliverables may also be governed by our [Master Services Agreement](/legal/msa) and applicable [Statement of Work](/legal/sow). If there is a conflict, the MSA/SOW controls for those services; these Terms control for general platform use.\r\n\r\n## 2. Accounts and access\r\n\r\n- You must provide accurate registration information and keep credentials confidential.\r\n- You are responsible for activity under your accounts.\r\n- We may suspend access for security, non-payment, misuse, or legal risk.\r\n\r\n## 3. Acceptable use\r\n\r\nYou will not:\r\n\r\n- Violate law or third-party rights\r\n- Probe, scan, or disrupt the Services\r\n- Upload malware or unlawful content\r\n- Misrepresent identity or affiliation\r\n- Resell the Services except as expressly permitted in writing\r\n- Use the Services to build a competing product using non-public materials\r\n\r\n## 4. Subscriptions and fees\r\n\r\nFees, renewals, and cancellation for paid subscriptions are described at checkout or in an order form. Payments are processed by Stripe or another designated processor. Taxes may apply. Late amounts may result in suspension.\r\n\r\n## 5. Intellectual property\r\n\r\nWe and our licensors own the Services, software, designs, templates, methodologies, documentation, and branding. Client retains ownership of Client content and data. Limited licenses are granted solely to use the Services as permitted.\r\n\r\n## 6. Client content\r\n\r\nYou grant us a limited license to host, process, and display Client content as needed to provide the Services. You represent you have rights to submit that content.\r\n\r\n## 7. AI features\r\n\r\nSome Services include AI-assisted features. See our [AI Disclosure](/legal/ai-disclosure). AI outputs may be inaccurate and require human review.\r\n\r\n## 8. Privacy\r\n\r\nOur [Privacy Policy](/legal/privacy) explains how we process personal information.\r\n\r\n## 9. Third-party services\r\n\r\nThe Services may integrate third-party tools. Those tools are governed by their own terms. We are not responsible for third-party outages beyond our reasonable control.\r\n\r\n## 10. Disclaimers\r\n\r\nTO THE MAXIMUM EXTENT PERMITTED BY LAW, THE SERVICES ARE PROVIDED “AS IS” AND “AS AVAILABLE.” WE DISCLAIM WARRANTIES OF MERCHANTABILITY, FITNESS FOR A PARTICULAR PURPOSE, AND NON-INFRINGEMENT.\r\n\r\n## 11. Limitation of liability\r\n\r\nTO THE MAXIMUM EXTENT PERMITTED BY LAW, OUR AGGREGATE LIABILITY ARISING OUT OF THESE TERMS WILL NOT EXCEED THE AMOUNTS PAID BY YOU TO US FOR THE SERVICES IN THE TWELVE (12) MONTHS BEFORE THE CLAIM. WE ARE NOT LIABLE FOR INDIRECT, INCIDENTAL, SPECIAL, CONSEQUENTIAL, OR PUNITIVE DAMAGES.\r\n\r\n## 12. Indemnity\r\n\r\nYou will defend and indemnify us against claims arising from your content, misuse of the Services, or violation of these Terms.\r\n\r\n## 13. Termination\r\n\r\nYou may stop using the Services at any time. We may terminate or suspend for material breach. Provisions that should survive will survive termination.\r\n\r\n## 14. Governing law\r\n\r\nThese Terms are governed by the laws of the State of North Carolina, excluding conflict-of-law rules. Exclusive venue lies in state or federal courts located in North Carolina, unless a signed MSA specifies otherwise.\r\n\r\n## 15. Changes\r\n\r\nWe may update these Terms by posting a revised version. Continued use after the effective date constitutes acceptance, except where acceptance must be captured separately (e.g., mobile onboarding).\r\n\r\n## 16. Contact\r\n\r\nfreedom@efficiencyarchitects.online  \r\n1848 Olsen Lane, Charlotte, NC 28213\r\n",
  "docs/legal/eula-v1.0.md": "# Mobile App End User License Agreement (EULA)\r\n\r\n**Ascension Systems**  \r\n**Version:** 1.0  \r\n**Document ID:** ASC-EULA-2026-1.0  \r\n**Effective Date:** July 21, 2026  \r\n**Last Updated:** July 21, 2026  \r\n**Status:** Active  \r\n**Applies to:** Simplifi, Simplifi Orb, and other Ascension Systems mobile applications\r\n\r\n---\r\n\r\n## 1. License grant\r\n\r\nSubject to this EULA and our [Terms of Service](/legal/terms), Ascension Systems grants you a personal, limited, non-exclusive, non-transferable, revocable license to install and use the mobile application (“**App**”) on devices you own or control.\r\n\r\n## 2. License restrictions\r\n\r\nYou may not copy, modify, reverse engineer, redistribute, rent, or sublicense the App except as permitted by law. You may not remove proprietary notices.\r\n\r\n## 3. App Store terms\r\n\r\nIf you downloaded the App from Apple App Store, Google Play, or another store, that store’s terms also apply. The store provider is not responsible for maintenance or support of the App unless required by the store’s rules. Claims relating to the App are between you and Ascension Systems, not the store provider, except where store rules require otherwise.\r\n\r\n## 4. Updates\r\n\r\nWe may provide updates that modify or replace the App. Some updates may be required to continue use.\r\n\r\n## 5. Data and permissions\r\n\r\nThe App may request access to camera, photos, microphone, notifications, contacts, or location only as needed for features you use (for example, Capture). See our [Privacy Policy](/legal/privacy).\r\n\r\n## 6. AI features\r\n\r\nIn-app AI assistance is subject to our [AI Disclosure](/legal/ai-disclosure).\r\n\r\n## 7. Ownership\r\n\r\nThe App and all related IP remain ours or our licensors’. No ownership transfer is implied.\r\n\r\n## 8. Disclaimer and liability\r\n\r\nTHE APP IS PROVIDED “AS IS.” LIABILITY LIMITS IN THE TERMS OF SERVICE APPLY TO THE APP.\r\n\r\n## 9. Termination\r\n\r\nThis license ends if you breach it or uninstall the App. We may terminate the license for misuse or legal risk.\r\n\r\n## 10. Contact\r\n\r\nfreedom@efficiencyarchitects.online\r\n",
  "docs/legal/ai-disclosure-v1.0.md": "# AI Disclosure\r\n\r\n**Ascension Systems**  \r\n**Version:** 1.0  \r\n**Document ID:** ASC-AI-2026-1.0  \r\n**Effective Date:** July 21, 2026  \r\n**Last Updated:** July 21, 2026  \r\n**Status:** Active\r\n\r\n---\r\n\r\n## 1. Purpose\r\n\r\nAscension Systems products (including Efficiency Architects, Simplifi, Amplifi, Magnifi, Fortifi, Unifi, Pulse, and related portals) may use artificial intelligence (“**AI**”) to assist with analysis, drafting, recommendations, routing, summarization, and similar features.\r\n\r\n## 2. Human oversight\r\n\r\nAI outputs are **assistive**, not a substitute for professional judgment. You are responsible for reviewing AI-generated content before relying on it for legal, financial, medical, safety, or operational decisions.\r\n\r\n## 3. Accuracy\r\n\r\nAI systems can produce incomplete, outdated, or incorrect results (“hallucinations”). We do not guarantee that AI outputs are error-free.\r\n\r\n## 4. Data use for AI features\r\n\r\nWhen you use AI features, relevant prompts, context, and content you provide may be processed by our systems and subprocessors (which may include third-party model providers) solely to deliver the feature, subject to our [Privacy Policy](/legal/privacy) and any Data Processing Addendum in a signed MSA.\r\n\r\nWe do not use Client confidential project content to train public foundation models unless a written agreement expressly authorizes it.\r\n\r\n## 5. Intellectual property of outputs\r\n\r\nSubject to third-party model terms and our [Terms of Service](/legal/terms), Client may use AI outputs generated for Client’s account for Client’s internal business purposes. We retain rights in underlying systems, prompts, templates, and tooling.\r\n\r\n## 6. Prohibited AI uses\r\n\r\nYou will not use AI features to generate unlawful content, to attempt to bypass security, or to make automated decisions with legal or similarly significant effects without appropriate human review where required by law.\r\n\r\n## 7. Changes\r\n\r\nWe may update models, prompts, and this Disclosure as the Services evolve.\r\n\r\n## 8. Contact\r\n\r\nfreedom@efficiencyarchitects.online\r\n",
  "docs/legal/support-policy-v1.0.md": "# Support Policy\r\n\r\n**Ascension Systems**  \r\n**Version:** 1.0  \r\n**Document ID:** ASC-SUPPORT-2026-1.0  \r\n**Effective Date:** July 21, 2026  \r\n**Last Updated:** July 21, 2026  \r\n**Status:** Active\r\n\r\n---\r\n\r\n## 1. Scope\r\n\r\nThis Support Policy describes how Ascension Systems provides support for platform products and related client experiences. Signed Statements of Work or subscription plans may provide enhanced support levels.\r\n\r\n## 2. Channels\r\n\r\n- Email: freedom@efficiencyarchitects.online  \r\n- In-product Help / Contact your guide (portal clients)  \r\n- Admin / ops channels for entitled enterprise clients\r\n\r\n## 3. Business hours\r\n\r\nSupport is generally monitored **Monday–Friday, 9:00 a.m.–5:00 p.m. U.S. Eastern Time**, excluding U.S. federal holidays, unless a signed agreement states otherwise.\r\n\r\n## 4. Response targets (best effort)\r\n\r\n| Priority | Examples | Target first response |\r\n|---|---|---|\r\n| Critical | Service fully unavailable for production clients | Within 1 business day |\r\n| High | Major feature broken; workaround limited | Within 1–2 business days |\r\n| Normal | Questions, how-to, non-blocking issues | Within 2–3 business days |\r\n\r\nThese are targets, not guarantees, unless an SLA is expressly included in a signed MSA/SOW.\r\n\r\n## 5. Client responsibilities\r\n\r\n- Provide accurate reproduction steps and account context\r\n- Maintain secure credentials\r\n- Designate a primary contact for paid engagements\r\n\r\n## 6. Exclusions\r\n\r\nSupport does not include unpaid custom development, third-party product support, or issues caused by Client modifications outside supported configuration.\r\n\r\n## 7. Contact\r\n\r\nfreedom@efficiencyarchitects.online\r\n",
  "docs/legal/cookie-policy-v1.0.md": "# Cookie Policy\r\n\r\n**Ascension Systems**  \r\n**Version:** 1.0  \r\n**Document ID:** ASC-COOKIE-2026-1.0  \r\n**Effective Date:** July 21, 2026  \r\n**Last Updated:** July 21, 2026  \r\n**Status:** Active  \r\n**Optional** by product configuration\r\n\r\n---\r\n\r\n## 1. What are cookies?\r\n\r\nCookies and similar technologies (local storage, pixels) store small amounts of data on your device to operate and improve our Services.\r\n\r\n## 2. Types we use\r\n\r\n- **Strictly necessary** — authentication, security, load balancing\r\n- **Preferences** — remembering settings\r\n- **Analytics** — aggregated usage to improve experiences (where enabled)\r\n- **Marketing** — only if a specific campaign feature is enabled and permitted\r\n\r\n## 3. Managing cookies\r\n\r\nYou can control cookies through browser or device settings. Blocking necessary cookies may break login or checkout.\r\n\r\n## 4. More information\r\n\r\nSee our [Privacy Policy](/legal/privacy). Questions: freedom@efficiencyarchitects.online\r\n",
  "docs/legal/msa-v1.0.md": "# Master Services Agreement\r\n\r\n**Ascension Systems**  \r\n**Version:** 1.0  \r\n**Document ID:** ASC-MSA-2026-1.0  \r\n**Effective Date:** July 21, 2026  \r\n**Last Updated:** July 21, 2026  \r\n**Status:** Active\r\n\r\n---\r\n\r\n**Ascension Systems**  \r\n1848 Olsen Lane  \r\nCharlotte, NC 28213  \r\nUnited States  \r\nEmail: freedom@efficiencyarchitects.online\r\n\r\nThis Master Services Agreement (the “**Agreement**”) is entered into by and between **Ascension Systems** (“**Provider**”) and the customer identified in an Order Form, Statement of Work, checkout record, or electronic acceptance (“**Client**”).\r\n\r\n## 1. Definitions\r\n\r\n**Deliverables**, **Professional Services**, **Subscription Services**, **Order Form**, and **SOW** have meanings set out in the applicable order documents. **Services** means Subscription Services and/or Professional Services.\r\n\r\n## 2. Scope\r\n\r\nThis Agreement governs Professional Services and related platform access purchased under Order Forms or SOWs. Online product use is also subject to the [Terms of Service](/legal/terms) and [Privacy Policy](/legal/privacy).\r\n\r\n## 3. Subscription Services\r\n\r\nProvider will provide entitled software modules as described in the Order Form. Client receives a non-exclusive license to use Subscription Services during the subscription term.\r\n\r\n## 4. Professional Services\r\n\r\nProvider will perform Professional Services (including websites, portals, guided project experiences, and related consulting) as described in each SOW.\r\n\r\n## 5. Statements of Work\r\n\r\nEach SOW is governed by this Agreement. If conflict exists, the SOW controls for that engagement’s scope and fees; this Agreement controls for legal terms.\r\n\r\n## 6. Fees and payment\r\n\r\nClient will pay fees as stated in the Order Form or SOW. Invoices are due as stated (typically upon receipt or Net 15). Late amounts may accrue interest at 1.5% per month or the maximum allowed by law. Provider may suspend work for non-payment.\r\n\r\n## 7. Taxes\r\n\r\nFees exclude taxes. Client is responsible for applicable taxes excluding taxes on Provider’s income.\r\n\r\n## 8. Client responsibilities\r\n\r\nClient will provide timely access, content, approvals, and a primary contact. Delays may extend timelines.\r\n\r\n## 9. Intellectual property\r\n\r\nProvider retains IP in methodologies, templates, software, engines (including Portal, Guide, Trust, and AI tooling), and pre-existing materials. Client retains Client branding, content, and data. Upon full payment, Client receives a license to use Deliverables for Client’s internal business purposes as stated in the SOW.\r\n\r\n## 10. Confidentiality\r\n\r\nEach party will protect the other’s Confidential Information and use it only to perform under this Agreement.\r\n\r\n## 11. Data protection\r\n\r\nProvider will process personal data as described in the Privacy Policy and any DPA executed by the parties.\r\n\r\n## 12. AI services\r\n\r\nAI-assisted features are subject to the [AI Disclosure](/legal/ai-disclosure).\r\n\r\n## 13. Warranties\r\n\r\nProvider warrants Professional Services will be performed in a professional manner. Subscription Services will materially conform to documentation under normal use. Exclusive remedy is re-performance or refund of the affected fees at Provider’s option.\r\n\r\n## 14. Disclaimer\r\n\r\nEXCEPT AS EXPRESSLY STATED, SERVICES ARE PROVIDED “AS IS” TO THE MAXIMUM EXTENT PERMITTED BY LAW.\r\n\r\n## 15. Limitation of liability\r\n\r\nEXCEPT FOR WILLFUL MISCONDUCT, BREACH OF CONFIDENTIALITY, OR IP INDEMNITY OBLIGATIONS, EACH PARTY’S AGGREGATE LIABILITY WILL NOT EXCEED FEES PAID BY CLIENT TO PROVIDER UNDER THE APPLICABLE SOW OR ORDER IN THE TWELVE (12) MONTHS BEFORE THE CLAIM. NEITHER PARTY IS LIABLE FOR INDIRECT OR CONSEQUENTIAL DAMAGES.\r\n\r\n## 16. Indemnification\r\n\r\nProvider will defend Client against third-party claims that Deliverables infringe IP, subject to customary exclusions. Client will defend Provider against claims arising from Client content or misuse.\r\n\r\n## 17. Term and termination\r\n\r\nThis Agreement continues until terminated. Either party may terminate for material breach uncured within 30 days’ notice. SOWs may have their own terms.\r\n\r\n## 18. E-sign and Trust records\r\n\r\nElectronic signatures and Trust Engine acceptance records are valid evidence of agreement.\r\n\r\n## 19. Governing law\r\n\r\nNorth Carolina law governs. Venue lies in North Carolina courts.\r\n\r\n## 20. General\r\n\r\nThis Agreement, with Order Forms and SOWs, is the entire agreement for Professional Services. Amendments must be in writing (including e-sign).\r\n\r\n---\r\n\r\n**Signature block** — executed via Order Form, e-signature platform, or Trust Engine acceptance record.\r\n",
  "docs/legal/sow-template-v1.0.md": "# Statement of Work (Template)\r\n\r\n**Ascension Systems**  \r\n**Version:** 1.0  \r\n**Document ID:** ASC-SOW-TEMPLATE-2026-1.0  \r\n**Effective Date:** July 21, 2026  \r\n**Last Updated:** July 21, 2026  \r\n**Status:** Active  \r\n**Note:** Engagement-specific SOWs are issued per Client. This template defines the standard structure.\r\n\r\n---\r\n\r\nThis Statement of Work (“**SOW**”) is issued under the [Master Services Agreement](/legal/msa) between Ascension Systems (“**Provider**”) and the Client named below.\r\n\r\n## 1. Client\r\n\r\n- Legal name: ______________________________\r\n- Primary contact: ______________________________\r\n- Email: ______________________________\r\n- Portal slug (if applicable): ______________________________\r\n\r\n## 2. Project summary\r\n\r\n- Project name: ______________________________\r\n- Product / offer: ______________________________\r\n- Objectives: ______________________________\r\n\r\n## 3. Scope of work\r\n\r\nDescribe in-scope Deliverables (e.g., Website + Guided Project Experience, portal configuration, content migration limits, training).\r\n\r\n## 4. Out of scope\r\n\r\nList exclusions (e.g., custom integrations, photography, ongoing ads management) unless added by change order.\r\n\r\n## 5. Timeline and milestones\r\n\r\n| Milestone | Target | Acceptance |\r\n|---|---|---|\r\n| Kickoff | | |\r\n| Design / draft | | |\r\n| Review | | |\r\n| Launch | | |\r\n\r\n## 6. Fees\r\n\r\n- Fixed fee / package: ______________________________\r\n- Payment schedule: ______________________________\r\n- Expenses: ______________________________\r\n\r\n## 7. Client responsibilities\r\n\r\nContent, brand assets, timely approvals, access credentials, and designated decision-maker.\r\n\r\n## 8. Acceptance\r\n\r\nDeliverables are accepted upon written approval or five (5) business days after delivery without written rejection specifying material non-conformance.\r\n\r\n## 9. Change orders\r\n\r\nMaterial scope changes require a written change order with fee/timeline impact.\r\n\r\n## 10. Incorporation\r\n\r\nThis SOW incorporates the MSA. Electronic signature or Trust Engine record constitutes execution.\r\n"
};

export function loadLegalMarkdown(sourcePath: string): string {
  const bundled = BUNDLE[sourcePath];
  if (!bundled) throw new Error('Legal source missing: ' + sourcePath);
  return bundled;
}
